from __future__ import annotations

import fnmatch
import json
import subprocess
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Literal

import yaml

from compost.model.frontmatter import parse_frontmatter


TriggerKind = Literal["source", "semantic", "path", "volume"]


@dataclass(frozen=True)
class Trigger:
    kind: TriggerKind
    pattern: str   # e.g. "incident", "postmortem", "raw/decisions/*", "5 in 7d"


@dataclass(frozen=True)
class ClassifyDecision:
    fired: bool
    triggers: list[Trigger]   # only matched triggers
    rationale: str            # one human-readable sentence


def load_rules(repo: Path) -> dict:
    """Load classifier rules: repo override (.compost/classifier_rules.yaml) first,
    then package-bundled default."""
    repo_override = repo / ".compost" / "classifier_rules.yaml"
    if repo_override.exists():
        with repo_override.open() as f:
            return yaml.safe_load(f)
    default_path = Path(__file__).parent / "classifier_rules.yaml"
    with default_path.open() as f:
        return yaml.safe_load(f)


def classify(
    raw_path: Path,
    repo: Path,
    rules: dict | None = None,
) -> ClassifyDecision:
    """Classify a raw file against the rules. Pure: does not write to disk."""
    if rules is None:
        rules = load_rules(repo)

    fm, body = parse_frontmatter(raw_path)
    source = fm.get("source", "")
    raw_rel_path = raw_path.relative_to(repo)

    triggers: list[Trigger] = []

    t = _check_source(source, rules)
    if t:
        triggers.append(t)

    triggers.extend(_check_semantic(fm, body, rules))

    t = _check_path(raw_rel_path, rules)
    if t:
        triggers.append(t)

    t = _check_volume(repo, source, rules)
    if t:
        triggers.append(t)

    fired = len(triggers) > 0

    if fired:
        parts = [f"{t.kind}:{t.pattern}" for t in triggers]
        n = len(triggers)
        rationale = (
            f"1 matched trigger: {parts[0]}"
            if n == 1
            else f"{n} matched triggers: {', '.join(parts)}"
        )
    else:
        rationale = "no triggers matched"

    return ClassifyDecision(fired=fired, triggers=triggers, rationale=rationale)


def log_decision(repo: Path, raw_rel_path: Path, decision: ClassifyDecision) -> None:
    """Append a classification event to .compost/classifications.jsonl."""
    log_dir = repo / ".compost"
    log_dir.mkdir(parents=True, exist_ok=True)
    entry = {
        "ts": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "raw_path": str(raw_rel_path).replace("\\", "/"),
        "fired": decision.fired,
        "triggers": [{"kind": t.kind, "pattern": t.pattern} for t in decision.triggers],
        "rationale": decision.rationale,
    }
    with (log_dir / "classifications.jsonl").open("a") as f:
        f.write(json.dumps(entry) + "\n")


# ── private helpers ───────────────────────────────────────────────────────────


def _check_source(source: str, rules: dict) -> Trigger | None:
    if source in rules.get("source_triggers", []):
        return Trigger(kind="source", pattern=source)
    return None


def _check_semantic(fm: dict, body: str, rules: dict) -> list[Trigger]:
    intent = str(fm.get("intent", ""))
    text = (body + " " + intent).lower()
    triggers = []
    for kw in rules.get("semantic_keywords", []):
        if kw.lower() in text:
            triggers.append(Trigger(kind="semantic", pattern=kw))
    return triggers


def _check_path(raw_rel_path: Path, rules: dict) -> Trigger | None:
    rel_str = str(raw_rel_path).replace("\\", "/")
    for pattern in rules.get("path_patterns", []):
        if fnmatch.fnmatch(rel_str, pattern):
            return Trigger(kind="path", pattern=pattern)
    return None


def _check_volume(
    repo: Path, source: str, rules: dict
) -> Trigger | None:
    threshold = rules.get("volume", {}).get("threshold", 5)
    window_days = rules.get("volume", {}).get("window_days", 7)

    candidates = _volume_candidates(repo, window_days)
    if candidates is None:
        return None

    count = sum(1 for f in candidates if _source_of(f) == source)

    if count >= threshold:
        return Trigger(kind="volume", pattern=f"{threshold} in {window_days}d")
    return None


def _volume_candidates(repo: Path, window_days: int) -> list[Path] | None:
    """Return raw/*.md files added within window_days. Uses git log if available, else mtime."""
    raw_dir = repo / "raw"
    if not raw_dir.exists():
        return None

    result = subprocess.run(
        [
            "git", "log",
            f"--since={window_days} days ago",
            "--diff-filter=A",
            "--name-only",
            "--format=",
            "--", "raw/",
        ],
        cwd=repo,
        capture_output=True,
        text=True,
    )
    if result.returncode == 0 and result.stdout.strip():
        paths = [
            repo / p.strip()
            for p in result.stdout.splitlines()
            if p.strip().endswith(".md")
        ]
        return [p for p in paths if p.exists()]

    # Fallback: mtime (non-git repo or no commits yet)
    cutoff_ts = (datetime.now(timezone.utc) - timedelta(days=window_days)).timestamp()
    return [f for f in raw_dir.rglob("*.md") if f.stat().st_mtime >= cutoff_ts]


def _source_of(f: Path) -> str:
    try:
        fm, _ = parse_frontmatter(f)
        return fm.get("source", "")
    except Exception:
        return ""

from __future__ import annotations

import sys
from pathlib import Path

import click

from compost.cli._helpers import console, _render_check_results


@click.group("checks")
def checks_group() -> None:
    """Tier 2.5 adversarial checks: verify wiki edits before merge."""


@checks_group.command("run")
@click.option("--branch", default=None,
              help="Branch to check. Defaults to current branch.")
@click.option("--raw", "raw_rel", default=None,
              help="Triggering raw file (relative to repo). Inferred from branch commits if omitted.")
@click.pass_context
def checks_run(ctx: click.Context, branch: str | None, raw_rel: str | None) -> None:
    """Run all adversarial checks on a branch and write a report."""
    from compost.checks.runner import run_checks, load_checks_config, infer_raw_path, write_check_report
    from compost.ingest.git import current_branch, default_branch
    from compost.repo import find_repo_root

    repo = ctx.obj["repo"] or find_repo_root(Path.cwd())
    if repo is None:
        console.print("[red]No .compost.yml found.[/red]")
        sys.exit(1)

    if branch is None:
        branch = current_branch(repo)

    base = default_branch(repo)

    if raw_rel:
        raw_path = repo / raw_rel
    else:
        raw_path = infer_raw_path(repo, branch, base)

    config = load_checks_config(repo)
    results = run_checks(repo, branch, raw_path, config=config)

    _render_check_results(results)

    report_path = write_check_report(repo, branch, results)
    console.print(f"[dim]report → {report_path.relative_to(repo)}[/dim]")

    if any(r.status == "fail" for r in results):
        sys.exit(1)

from __future__ import annotations

from pathlib import Path
from typing import Literal, TypedDict

import frontmatter as fm_lib

FrontmatterType = Literal[
    "service", "module", "decision", "runbook", "concept",
    "customer", "person", "project", "research",
]

REQUIRED_FIELDS = ("type", "name", "owners", "status", "updated",
                   "confidence", "sources")


class Frontmatter(TypedDict, total=False):
    type: FrontmatterType
    name: str
    owners: list[str]
    status: Literal["active", "deprecated", "archived"]
    updated: str
    confidence: Literal["high", "medium", "low"]
    sources: list[str]
    related: list[str]
    supersedes: list[str]
    superseded_by: str | None


def parse_frontmatter(path: Path) -> tuple[dict, str]:
    """Return (frontmatter_dict, body_text). Never raises; returns empty dict on parse failure."""
    try:
        post = fm_lib.load(str(path))
        return dict(post.metadata), post.content
    except Exception:
        return {}, path.read_text()


def validate_frontmatter(fm: dict, rel_path: Path) -> list[str]:
    """Return a list of human-readable error strings. Empty list means valid."""
    errors: list[str] = []
    prefix = str(rel_path)

    for field in REQUIRED_FIELDS:
        if field not in fm:
            errors.append(f"{prefix}: missing required field '{field}'")

    if "sources" in fm:
        if not fm["sources"]:
            errors.append(f"{prefix}: 'sources' must be non-empty")

    if "owners" in fm:
        if not fm["owners"]:
            errors.append(f"{prefix}: 'owners' must be non-empty")

    if "type" in fm:
        valid_types = {
            "service", "module", "decision", "runbook", "concept",
            "customer", "person", "project", "research",
        }
        if fm["type"] not in valid_types:
            errors.append(f"{prefix}: unknown type '{fm['type']}'")

    if "confidence" in fm:
        if fm["confidence"] not in ("high", "medium", "low"):
            errors.append(f"{prefix}: confidence must be high|medium|low")

    if "status" in fm:
        if fm["status"] not in ("active", "deprecated", "archived"):
            errors.append(f"{prefix}: status must be active|deprecated|archived")

    return errors

from __future__ import annotations

import sys
from pathlib import Path

import click
from rich.table import Table

from compost.cli._helpers import console, _print_classify_verdict


@click.group("classify")
def classify_group() -> None:
    """Run Tier 1 classifier on raw files."""


@classify_group.command("run")
@click.argument("raw_path", type=click.Path(exists=True, resolve_path=True, path_type=Path))
@click.option("--dry-run", is_flag=True, help="Classify without logging the result.")
@click.pass_context
def classify_run(ctx: click.Context, raw_path: Path, dry_run: bool) -> None:
    """Classify a raw file and print the Tier 1 verdict."""
    from compost.ingest.classifier import classify, log_decision
    from compost.repo import find_repo_root

    repo = ctx.obj["repo"] or find_repo_root(Path.cwd())
    if repo is None:
        console.print("[red]No .compost.yml found.[/red]")
        sys.exit(1)

    try:
        rel = raw_path.relative_to(repo)
    except ValueError:
        console.print(f"[red]{raw_path} is not under the repo root {repo}[/red]")
        sys.exit(1)

    decision = classify(raw_path, repo)

    if not dry_run:
        log_decision(repo, rel, decision)

    _print_classify_verdict(rel, decision)


@classify_group.command("replay")
@click.option("--since", default="7d", show_default=True,
              help="How far back to scan (e.g. 7d, 30d).")
@click.pass_context
def classify_replay(ctx: click.Context, since: str) -> None:
    """Classify all raw/*.md files modified within a rolling window (dry-run; no logging)."""
    import re
    from datetime import datetime, timedelta, timezone as tz
    from compost.ingest.classifier import classify
    from compost.repo import find_repo_root

    repo = ctx.obj["repo"] or find_repo_root(Path.cwd())
    if repo is None:
        console.print("[red]No .compost.yml found.[/red]")
        sys.exit(1)

    m = re.fullmatch(r"(\d+)d", since.strip())
    if not m:
        console.print("[red]--since must be in Nd format (e.g. 7d, 30d)[/red]")
        sys.exit(1)

    days = int(m.group(1))
    cutoff_ts = (datetime.now(tz.utc) - timedelta(days=days)).timestamp()

    raw_dir = repo / "raw"
    if not raw_dir.exists():
        console.print("[dim]No raw/ directory found.[/dim]")
        return

    files = sorted(
        (f for f in raw_dir.rglob("*.md") if f.stat().st_mtime >= cutoff_ts),
        key=lambda f: f.stat().st_mtime,
        reverse=True,
    )

    if not files:
        console.print("[dim]No files found within window.[/dim]")
        return

    table = Table(show_header=True, box=None, padding=(0, 1))
    table.add_column("path")
    table.add_column("fired")
    table.add_column("triggers")

    for f in files:
        try:
            decision = classify(f, repo)
        except Exception:
            continue
        rel = f.relative_to(repo)
        fired_str = "[green]FIRE[/green]" if decision.fired else "[dim]-[/dim]"
        triggers_str = (
            ", ".join(f"{t.kind}:{t.pattern}" for t in decision.triggers)
            or "(none)"
        )
        table.add_row(str(rel), fired_str, triggers_str)

    console.print(table)

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import httpx


class GiteaError(Exception):
    def __init__(self, message: str, status: int = 0) -> None:
        super().__init__(message)
        self.status = status


@dataclass(frozen=True)
class GiteaPR:
    number: int
    url: str
    state: str   # "open" | "closed" | "merged"


class GiteaClient:
    def __init__(
        self,
        url: str,
        owner: str,
        repo: str,
        token: str,
        *,
        _transport: httpx.BaseTransport | None = None,
    ) -> None:
        if not token:
            raise GiteaError("GITEA_TOKEN is not set")
        self._base = url.rstrip("/")
        self._owner = owner
        self._repo = repo
        self._http = httpx.Client(
            headers={
                "Authorization": f"token {token}",
                "Content-Type": "application/json",
            },
            transport=_transport,
        )

    def __repr__(self) -> str:
        return f"GiteaClient(url={self._base!r}, owner={self._owner!r}, repo={self._repo!r})"

    def _request(
        self, method: str, path: str, body: dict | None = None, **params: Any
    ) -> dict | list | None:
        url = f"{self._base}/api/v1{path}"
        r = self._http.request(method, url, json=body, params=params or None)
        if r.status_code >= 400:
            try:
                msg = r.json().get("message", r.text)
            except Exception:
                msg = r.text
            raise GiteaError(f"{r.status_code} {method} {path}: {msg}", status=r.status_code)
        return r.json() if r.content else None

    def get_authenticated_user(self) -> str:
        data = self._request("GET", "/user")
        return data["login"]

    def create_repo(self, name: str, private: bool = False) -> None:
        """Create repo under owner. No-op if already exists."""
        try:
            self._request("GET", f"/repos/{self._owner}/{name}")
            return
        except GiteaError as e:
            if e.status != 404:
                raise
        self._request("POST", "/user/repos", {"name": name, "private": private})

    def get_clone_url(self, name: str, ssh: bool = False) -> str:
        """Return the clone URL for the repo as reported by Gitea (HTTP or SSH)."""
        data = self._request("GET", f"/repos/{self._owner}/{name}")
        return data["ssh_url"] if ssh else data["clone_url"]

    def open_pr(self, branch: str, base: str, title: str, body: str) -> GiteaPR:
        data = self._request(
            "POST",
            f"/repos/{self._owner}/{self._repo}/pulls",
            {"head": branch, "base": base, "title": title, "body": body},
        )
        return GiteaPR(number=data["number"], url=data["html_url"], state=data["state"])

    def find_pr(self, branch: str) -> GiteaPR | None:
        prs = self._request(
            "GET",
            f"/repos/{self._owner}/{self._repo}/pulls",
            state="open",
            limit=50,
        )
        for pr in (prs or []):
            if pr["head"]["ref"] == branch:
                return GiteaPR(number=pr["number"], url=pr["html_url"], state=pr["state"])
        return None

    def merge_pr(self, pr_number: int) -> None:
        self._request(
            "POST",
            f"/repos/{self._owner}/{self._repo}/pulls/{pr_number}/merge",
            {"do": "merge"},
        )

from __future__ import annotations

import subprocess
from pathlib import Path

import click


def _to_rel(f: Path, repo: Path) -> Path:
    return f.relative_to(repo) if f.is_absolute() else f


def assert_git_repo(repo: Path) -> None:
    """Raise click.UsageError if repo has no .git directory."""
    if not (repo / ".git").exists():
        raise click.UsageError(
            f"{repo} is not a git repository. Run `git init` first."
        )


def get_git_user_name(repo: Path) -> str:
    """Return git config user.name, or empty string if not set."""
    result = subprocess.run(
        ["git", "config", "user.name"],
        cwd=repo, capture_output=True, text=True,
    )
    return result.stdout.strip()


def default_branch(repo: Path) -> str:
    """Return the repo's default branch name (main or master)."""
    for branch in ("main", "master"):
        result = subprocess.run(
            ["git", "rev-parse", "--verify", branch],
            cwd=repo, capture_output=True,
        )
        if result.returncode == 0:
            return branch
    return current_branch(repo)


def current_branch(repo: Path) -> str:
    """Return the current branch name."""
    result = subprocess.run(
        ["git", "rev-parse", "--abbrev-ref", "HEAD"],
        cwd=repo, capture_output=True, text=True, check=True,
    )
    return result.stdout.strip()


def create_branch_and_commit(
    repo: Path,
    branch: str,
    files: list[Path],
    message: str,
) -> None:
    """Create branch off current HEAD, stage files, commit."""
    result = subprocess.run(
        ["git", "checkout", "-b", branch],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise click.UsageError(
            f"Cannot create branch '{branch}': {result.stderr.strip()}"
        )

    for f in files:
        subprocess.run(["git", "add", str(_to_rel(f, repo))], cwd=repo, check=True)

    result = subprocess.run(
        ["git", "commit", "-m", message],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise click.UsageError(f"Commit failed: {result.stderr.strip()}")


def stage_and_commit(repo: Path, files: list[Path], message: str) -> None:
    """Stage files and commit on the current branch. Does not create a new branch."""
    for f in files:
        subprocess.run(["git", "add", str(_to_rel(f, repo))], cwd=repo, check=True)
    result = subprocess.run(
        ["git", "commit", "-m", message],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip()
        raise click.UsageError(f"Commit failed: {detail}")


def changed_files(repo: Path, branch: str, base: str) -> list[str]:
    """Return paths changed on branch relative to base (three-dot diff)."""
    result = subprocess.run(
        ["git", "diff", "--name-only", f"{base}...{branch}"],
        cwd=repo, capture_output=True, text=True, check=True,
    )
    return [line for line in result.stdout.splitlines() if line]


def fast_forward_merge(repo: Path, branch: str) -> None:
    """Fast-forward merge branch into current branch. Errors if not FF-able."""
    result = subprocess.run(
        ["git", "merge", "--ff-only", branch],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise click.UsageError(
            f"Cannot fast-forward merge '{branch}': {result.stderr.strip()}"
        )


def push_branch(repo: Path, remote: str, branch: str) -> None:
    """Push branch to remote, setting tracking. Raises click.UsageError on failure."""
    result = subprocess.run(
        ["git", "push", "--set-upstream", remote, branch],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise click.UsageError(
            f"Push failed: {result.stderr.strip()}\n"
            f"Retry manually: git push {remote} {branch}"
        )


def fetch_and_ff(repo: Path, remote: str, branch: str) -> None:
    """Fetch from remote, checkout branch, fast-forward to remote tracking ref."""
    subprocess.run(["git", "fetch", remote], cwd=repo, check=True, capture_output=True)

    result = subprocess.run(
        ["git", "checkout", branch],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise click.UsageError(f"Cannot checkout '{branch}': {result.stderr.strip()}")

    result = subprocess.run(
        ["git", "merge", "--ff-only", f"{remote}/{branch}"],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise click.UsageError(
            f"Cannot fast-forward '{branch}' to '{remote}/{branch}': {result.stderr.strip()}"
        )


def set_remote_url(repo: Path, remote: str, url: str) -> None:
    """Add remote if missing, or update its URL if it already exists."""
    result = subprocess.run(
        ["git", "remote", "get-url", remote],
        cwd=repo, capture_output=True,
    )
    if result.returncode == 0:
        subprocess.run(
            ["git", "remote", "set-url", remote, url],
            cwd=repo, check=True, capture_output=True,
        )
    else:
        subprocess.run(
            ["git", "remote", "add", remote, url],
            cwd=repo, check=True, capture_output=True,
        )


def get_remote_url(repo: Path, remote: str) -> str | None:
    """Return the URL for a remote, or None if the remote doesn't exist."""
    result = subprocess.run(
        ["git", "remote", "get-url", remote],
        cwd=repo, capture_output=True, text=True,
    )
    if result.returncode != 0:
        return None
    return result.stdout.strip()

